    spider.LeftSurface = Enum.SurfaceType.Smooth
    spider.Massless = true
    spider.Material = Enum.Material.Plastic
    spider.Reflectance = 0
    spider.RightSurface = Enum.SurfaceType.Smooth
    spider.RootPriority = -5
