        frame.BackgroundTransparency = 1
        frame.BorderSizePixel = 0
        frame.Position = UDim2.new(edgeX, 0, 0.558, 0)
        frame.Size = UDim2.new(0.2612044513, 0, 1, 0)
        frame.ZIndex = 99
        frame.Parent = mainFrame

        local layout = Instance.new("UIListLayout")
