    }, TabMethods)

    tab._applySearch = Protected[4](tab)
    tab._searchQuery = ""

    table.insert(self.Tabs, tab)
    self._tabByName[tab.Name] = tab
    connectSafeActivation(button, function()
        ApiImpl[94](self, tab)
    end)

    ApiImpl[93](self)
    if not self.SelectedTab then
        ApiImpl[94](self, tab)
    else
        setTabSelected(tab, false)
    end
    return tab
end


