        _stateByName = {},
        _tabByName = {},
        ExclusiveGroups = {},
        Name = windowConfig.Name,
        SelectedTab = nil,
        States = {},
        Tabs = {},
    }, WindowMethods)

    self.Window = window
    ContentScale.ReflowTabs = function()
        if not window._destroyed then
            ApiImpl[93](window)
        end
    end
    window.DefaultTab = ApiImpl[95](window,
        tostring(windowConfig.DefaultTab or "Main")
    )
    return window
end








